                results.push({ id: svc.id, status, latency, httpStatus: res.status });
            } catch (err) {
                const prev = this.snapshots.get(`connectivity:${svc.id}`);
                if (prev?.data?.status !== "down") {
                    this.snapshot(`connectivity:${svc.id}`, { status: "down", error: err.message });
                }
