        'dormant', 'minimal', 'low', 'moderate', 'steady',
        'active', 'elevated', 'high', 'intense', 'peak',
        'surge', 'critical', 'maximum'
    ];
    return { tier, label: labels[tier], base13: toBase13(tier) };
}

